  id uuid NOT NULL DEFAULT gen_random_uuid(),
  student_id text NOT NULL,
  day date NOT NULL,
  commits integer NOT NULL DEFAULT 0,
  pull_requests integer NOT NULL DEFAULT 0,
  reviews integer NOT NULL DEFAULT 0,
  score numeric NOT NULL DEFAULT '0'::numeric,
  tenant_id uuid
);

CREATE TABLE IF NOT EXISTS public.student_oss_contributions (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  student_id text NOT NULL,
  tenant_id uuid,
  project_id uuid,
  repo_url text NOT NULL,
  pr_url text NOT NULL,
  pr_number integer,
  title text NOT NULL DEFAULT ''::text,
  contribution_type text NOT NULL DEFAULT 'pr'::text,
  status text NOT NULL DEFAULT 'claimed'::text,
  merged_at timestamp with time zone,
  files_changed integer NOT NULL DEFAULT 0,
  lines_added integer NOT NULL DEFAULT 0,
  lines_deleted integer NOT NULL DEFAULT 0,
  verified_at timestamp with time zone,
  created_at timestamp with time zone NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.student_roadmap_progress (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  student_id text NOT NULL,
  node_id text NOT NULL,
  status text NOT NULL,
  evidence_source text,
  completed_at timestamp with time zone,
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  tenant_id uuid
);

CREATE TABLE IF NOT EXISTS public.tenant_domains (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL,
  domain text NOT NULL,
  is_primary boolean NOT NULL DEFAULT false,
  created_at timestamp with time zone NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.tenants (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  slug text NOT NULL,
  name text NOT NULL,
  status text NOT NULL DEFAULT 'active'::text,
  created_at timestamp with time zone NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.user_endorsements (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  endorser_id text NOT NULL,
  endorsee_id text NOT NULL,
  skill text NOT NULL,
  endorsed_at timestamp with time zone NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.user_profiles (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  user_id text NOT NULL,
  tenant_id uuid,
  username text NOT NULL,
  bio text NOT NULL DEFAULT ''::text,
  avatar_url text,
  location text,
  social_links jsonb NOT NULL DEFAULT '{}'::jsonb,
  primary_domain text,
  is_public boolean NOT NULL DEFAULT true,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.verifiable_credentials (
  id text NOT NULL,
  student_id text NOT NULL,
  tenant_id uuid,
  achievement_id uuid,
  credential_type text NOT NULL DEFAULT 'badge'::text,
  title text NOT NULL,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  issued_at timestamp with time zone NOT NULL DEFAULT now(),
  expires_at timestamp with time zone,
  signature text NOT NULL,
  view_count integer NOT NULL DEFAULT 0,
  last_verified_at timestamp with time zone
);

CREATE TABLE IF NOT EXISTS public.volunteer_signups (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  slot_id uuid NOT NULL,
  user_id text NOT NULL,
  created_at timestamp with time zone NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.volunteer_slots (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  tenant_id uuid,
  event_id uuid NOT NULL,
  title text NOT NULL,
  capacity integer NOT NULL DEFAULT 10,
  created_by text NOT NULL,
  created_at timestamp with time zone NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.wiki_edit_requests (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  page_id uuid NOT NULL,
  requester_id text NOT NULL,
  proposed_title text,
  proposed_content text NOT NULL DEFAULT ''::text,
  reason text NOT NULL DEFAULT ''::text,
  status text NOT NULL DEFAULT 'pending'::text,
  created_at timestamp with time zone NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.wiki_pages (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  tenant_id uuid,
  slug text NOT NULL,
  title text NOT NULL,
  content text NOT NULL DEFAULT ''::text,
  domain text NOT NULL DEFAULT 'general'::text,
  author_id text NOT NULL,
  version integer NOT NULL DEFAULT 1,
  status text NOT NULL DEFAULT 'published'::text,
  view_count integer NOT NULL DEFAULT 0,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now()
);

